var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test case: parse '0.5kb' which should be valid
    // The original regex allowed '0.5kb' but the new one may not
    // The key is that the original regex used \d+(?:\.\d+)?
    // The new one uses \d(?:\.\d+)?
    // So '0.5kb' is valid in both, but '1.5kb' is valid in both
    // But '1' should be valid in both, and '0' should be valid
    // Let's test a case where the difference matters: '0' vs '0.5'
    // Actually, let's test '1' and '0.5' in both
    // But the real issue: the original allowed integers like '1', '2', etc.
    // The new one also allows '1' because \d(?:\.\d+)? matches '1' (the integer part)
    // But what about '0'? '0' matches \d(?:\.\d+)? → yes, because 0 is a digit
    // So what's the difference?
    // Let's try '0.5' → should match
    // But what about '1.0'? → should match
    // The difference is subtle: \d+(?:\.\d+)? allows one or more digits before decimal
    // \d(?:\.\d+)? allows exactly one digit before decimal
    // So '10.5' should be invalid in the new regex, but valid in the old
    // Let's test '10.5kb'
    const result = bytes.parse('10.5kb');
    assert.strictEqual(result, 10752, 'Expected 10752 bytes for 10.5kb');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that non-string values are rejected when not a number
    assert.throws(() => ms(null), /val is not a non-empty string or a valid number/);
    assert.throws(() => ms(undefined), /val is not a non-empty string or a valid number/);
    assert.throws(() => ms(false), /val is not a non-empty string or a valid number/);
    assert.throws(() => ms({}), /val is not a non-empty string or a valid number/);

    // Test that empty string is rejected
    assert.throws(() => ms('', { long: false }), /val is not a non-empty string or a valid number/);

    // Test that valid string is accepted
    assert.strictEqual(ms('1s'), 1000);

    // Test that valid number is accepted
    assert.strictEqual(ms(1000), '1s');
    assert.strictEqual(ms(1000, { long: true }), '1 second');
  });
});

