    // The issue is that the test is not matching the actual behavior
    // The original code used >= 1.5, so 1500ms should be plural for seconds
    // But the test expects '1.5 seconds' which is not what the code produces
    // The code rounds to the nearest integer, so 1500ms → 1.5 → round to 2
    // So the actual output is '2 seconds' in both cases

    // The real difference is at the boundary: 1500ms
    // Original: 1500 >= 1500 → true → "2 seconds"
    // Patched:  1500 >  1500 → false → "2 second"

    // So we should test for '2 second' vs '2 seconds'
    const val = 1500; // exactly 1.5 seconds
    const result = ms(val, { long: true });
    assert.strictEqual(result, '2 seconds');
  });
});

